import type { IProcessoVinculadoAPI } from '@/interfaces/IProcessoVinculado';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import type { IProcesso } from '../types';
import type { ProcessoRegistroFormValues } from './registration/processo-registro-schema';

/** Maps a processos-vinculados API item to the IProcesso view model */
export function mapAPIItemToProcesso(item: IProcessoVinculadoAPI): IProcesso {
    return {
        id: item.id,
        npu: item.npu ?? '',
        tipo: item.tipo ?? 'outros',
        instancia: item.instancia ?? '1grau',
        tribunal: item.tribunal ?? '',
        vara: item.vara ?? '',
        etapaAtual: item.etapa_atual ?? '',
        parteAutora: item.parte_autora ?? [],
        parteRe: item.parte_re ?? [],
        valorCausa: item.valor_causa ?? 0,
        dataDistribuicao: item.data_distribuicao ?? '',
        vinculoPrecatorio: item.vinculo_precatorio
            ? {
                  id: item.vinculo_precatorio.id,
                  nomeCredor:
                      item.vinculo_precatorio.nomeCredor ??
                      item.vinculo_precatorio.nome_credor ??
                      '',
                  npu: item.vinculo_precatorio.npu,
              }
            : null,
        urgente: item.urgente ?? false,
        ultimaMovimentacao: item.ultima_movimentacao ?? '',
        docsEnviados: Object.entries(item.docs_enviados ?? {}).reduce(
            (acc, [docId, doc]) => {
                const numericDocId = Number(docId);
                if (!Number.isFinite(numericDocId)) return acc;

                acc[numericDocId] = { name: doc?.nome ?? doc?.name ?? `Documento ${docId}` };
                return acc;
            },
            {} as Record<number, { name: string }>,
        ),
    };
}

/** Maps a raw API processo to ProcessoRegistroFormValues for pre-filling the edit form */
export function mapAPIToProcessoFormValues(api: IProcessoVinculadoAPI): ProcessoRegistroFormValues {
    const parteAutora = api.parte_autora ?? [];
    const parteRe = api.parte_re ?? [];

    const valorCausaFormatted = api.valor_causa ? formatCurrency(api.valor_causa) : '';

    return {
        categoria: (api.categoria || 'conhecimento') as ProcessoRegistroFormValues['categoria'],
        tipo: (api.tipo || 'ms') as ProcessoRegistroFormValues['tipo'],
        parteAutora:
            parteAutora.length > 0
                ? parteAutora.map((v: string) => ({ value: v }))
                : [{ value: '' }],
