function normalizeTipoDoOficio(value?: string | null): string {
    const normalized = String(value ?? '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .trim()
        .toUpperCase();

    if (normalized === 'PRECATORIO') return 'PRECATÓRIO';
    if (normalized === 'CREDITORIO') return 'CREDITÓRIO';
